#!/usr/bin/env python3
"""Install NukeFire Client Milestone 1.5a2 Styled Communications safely."""
from __future__ import annotations

import base64
import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import zlib

MILESTONE = "Milestone 1.5a2 — Styled Communications"
BASELINE_HASHES = {'BUILD-MILESTONE.txt': '0b7787f6d2e76b737208337a837ea567d98e96ed3493150efca6cb3dc28cab88', 'CHANGELOG.md': 'cebcfe88bf04ecc50c339fcbea7cfecf2c50c402cedeea2abae06c720adc1826', 'renderer/renderer.js': 'bf79f82df51d7c2f6ab7384c55b8899b455a238da3071ea050cc7db98d185a4d', 'renderer/styles.css': 'f939bbf62e5162a6ffcd1156e479ffb3236e92be0b584a89ee4be5bee3961e84', 'src/communications.js': '71d1360c607442294f404f1b6ed2acc23ceb30b4abe181791c15f7fe47cdeda9', 'test/communications.test.js': 'c31dd3e30514c81729bfc58ac842fb08d940c1a2ab159da544c31cb2287608ea', 'test/communications-panel.test.js': '40f7787ae7a7d4f992c90ed95789f72df60c5eeffe8a06f5bc2a595eda204ec7'}
TARGET_HASHES = {'BUILD-MILESTONE.txt': '64b1cbcced622aee88cbda10be96d34ec436af54b6ee2747aadeb6bb594a553a', 'CHANGELOG.md': '426c4c92a7d5686410069d4ffbffe43b2c9e80beb529b954c9e71933e17968e9', 'renderer/renderer.js': 'e272be7ddeb7f42a51120d404531864843a6b392e956efe4119e852cbab93d99', 'renderer/styles.css': 'e49b43ba0506331197716c943fd59dd0d36b04f7ae0f7eb50d2162d431ec033c', 'src/communications.js': '9d6c6e699638e052cec3b024b0985cff0940754d94b4b4004b25ed5335cee230', 'test/communications.test.js': 'accbc283aa5ad2f45fc0d53ec95fa293d2efa62d20afbd5884d8033cc90c81f0', 'test/communications-panel.test.js': '17789a3f8d380df4fa282489edad54b071065dd266c37bf103d6783f1dba44f6'}
PAYLOAD = ''


def digest(path: Path) -> str | None:
    if not path.is_file():
        return None
    return hashlib.sha256(path.read_bytes()).hexdigest()


def load_payload() -> dict[str, bytes]:
    packed = zlib.decompress(base64.b64decode(PAYLOAD.encode("ascii")))
    data = json.loads(packed.decode("utf-8"))
    return {name: base64.b64decode(content) for name, content in data.items()}


def run_verify(root: Path) -> None:
    result = subprocess.run(["npm", "run", "verify"], cwd=root)
    if result.returncode != 0:
        raise RuntimeError("npm run verify failed")


def main() -> int:
    root = Path.cwd().resolve()
    if not (root / "package.json").is_file() or not (root / "renderer" / "renderer.js").is_file():
        print("Run this installer from the NukeFire client repository beside package.json.", file=sys.stderr)
        return 2

    current = {name: digest(root / name) for name in BASELINE_HASHES}
    if current == TARGET_HASHES:
        print(f"{MILESTONE} is already installed. Running verification...")
        run_verify(root)
        print("Verification passed.")
        return 0

    mismatches = [
        name for name, expected in BASELINE_HASHES.items()
        if current.get(name) != expected
    ]
    if mismatches:
        print("The working tree does not match the verified Milestone 1.5a1 baseline.", file=sys.stderr)
        print("Unexpected files:", file=sys.stderr)
        for name in mismatches:
            print(f"  {name}", file=sys.stderr)
        print("No files were changed.", file=sys.stderr)
        return 3

    payload = load_payload()
    backup_dir = Path(tempfile.mkdtemp(prefix="nukefire-1.5a2-backup-"))
    try:
        for name in payload:
            source = root / name
            backup = backup_dir / name
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, backup)

        for name, content in payload.items():
            destination = root / name
            destination.parent.mkdir(parents=True, exist_ok=True)
            temporary = destination.with_name(destination.name + ".1.5a2.tmp")
            temporary.write_bytes(content)
            temporary.replace(destination)

        installed = {name: digest(root / name) for name in TARGET_HASHES}
        if installed != TARGET_HASHES:
            raise RuntimeError("installed file hashes did not match the verified target")

        run_verify(root)
    except Exception as error:
        print(f"Installation failed: {error}", file=sys.stderr)
        print("Restoring the Milestone 1.5a1 files...", file=sys.stderr)
        for name in payload:
            backup = backup_dir / name
            if backup.is_file():
                destination = root / name
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(backup, destination)
        return 4
    finally:
        shutil.rmtree(backup_dir, ignore_errors=True)

    print(f"{MILESTONE} installed successfully.")
    print("Communications now preserves safe ANSI, 256-color, and truecolor styling.")
    print("Search and duplicate detection continue to use clean plain text.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
